function send(res, status, body, type = 'application/json; charset=utf-8', headers = {}) { res.writeHead(status, { 'content-type': type, ...headers }); res.end(type.startsWith('application/json') ? JSON.stringify(body) : body); }
function redirect(res, location) { res.writeHead(302, { location }); res.end(); }
function cookie(req, name) { return (req.headers.cookie || '').split(';').map(v => v.trim().split('=')).find(([key]) => key === name)?.[1]; }
async function body(req) { let raw = ''; for await (const chunk of req) { raw += chunk; if (raw.length > MAX_BODY) throw new Error('El cuerpo supera el límite permitido.'); } return raw ? JSON.parse(raw) : {}; }
function userFor(req) { const token = cookie(req, 'stores_session'); return token ? sessions.get(token) : null; }
function canAccess(user, storeId) { return user?.role === 'master' || user?.storeIds?.includes(storeId); }
function normalizeOrigin(value) { try { return new URL(String(value || '')).origin.toLowerCase(); } catch { return ''; } }
function findStore(value) { return db.data.stores.find(store => store.id === value || store.slug === value || normalizeOrigin(store.origin) === normalizeOrigin(value)); }
function publicStore(store) { const { apiKey, ...safeStore } = store; return safeStore; }
const DEFAULT_WHATSAPP_MESSAGE = 'Hola, Importaciones EBC. Quiero solicitar este pedido y confirmar disponibilidad, envío y forma de pago:';
const DEFAULT_WHATSAPP_GREETING = 'Hola, Importaciones EBC. Quiero conocer sus productos y recibir asesoría, por favor.';
const DEFAULT_LOCATION_TITLE = 'Ubicación';
const DEFAULT_LOCATION_ADDRESS = 'Cr 8 #7-39, barrio Obrero, Calima-Darién';
function settingsWithDefaults(store, settings = db.data.settings.find(item => item.storeId === store.id)) { return { storeId: store.id, storeName: store.name, ...settings, whatsappMessage: String(settings?.whatsappMessage || '').trim() || DEFAULT_WHATSAPP_MESSAGE, whatsappGreeting: String(settings?.whatsappGreeting || '').trim() || DEFAULT_WHATSAPP_GREETING, locationTitle: String(settings?.locationTitle || '').trim() || DEFAULT_LOCATION_TITLE, locationAddress: String(settings?.locationAddress || '').trim() || DEFAULT_LOCATION_ADDRESS }; }
function generatedDetails(product, category) { const categoryName = category?.name || 'producto seleccionado'; const short = String(product.description || '').replace(/<[^>]*>/g, '').trim(); return `<p><strong>${text(product.name)}</strong> es una opción seleccionada de nuestra categoría de ${text(categoryName).toLowerCase()}.</p>${short ? `<p>${text(short)}</p>` : `<p>Una alternativa práctica para complementar tu rutina y recibirla directamente en Colombia.</p>`}<h3>Compra acompañada</h3><ul><li>Producto revisado antes de confirmar disponibilidad.</li><li>Precio de referencia sujeto a disponibilidad y envío.</li><li>Te asesoramos por WhatsApp para coordinar tu pedido.</li></ul>`; }
function detailsForProduct(product, categories) { return { ...product, detailsHtml: String(product.detailsHtml || '').trim() || generatedDetails(product, categories.find(category => category.id === product.categoryId)) }; }
function publicCatalog(store) { const categories = db.data.categories.filter(item => item.storeId === store.id && item.active).sort((a,b) => a.sortOrder-b.sortOrder); const products = db.data.products.filter(item => item.storeId === store.id && item.active && item.available).sort((a,b) => a.sortOrder-b.sortOrder).map(product => detailsForProduct(product, categories)); return { store: publicStore(store), settings: settingsWithDefaults(store), categories, products, featuredProducts: products.filter(product => product.featured) }; }
function validateRecord(collectionName, input) {
  if (collectionName === 'categories' && !cleanText(input.name, 120)) throw new Error('El nombre de la categoría es obligatorio.');
  if (collectionName === 'products' && (!cleanText(input.name, 160) || !input.categoryId || Number(input.price) < 0)) throw new Error('Producto inválido: nombre, categoría y precio son obligatorios.');
  if (collectionName === 'products' && input.previousPrice !== '' && input.previousPrice != null && Number(input.previousPrice) <= Number(input.price)) throw new Error('El precio anterior debe ser mayor que el precio actual.');
  if (collectionName === 'settings' && input.whatsappNumber && !/^\d{8,15}$/.test(String(input.whatsappNumber).replace(/\D/g, ''))) throw new Error('El número de WhatsApp debe contener solo dígitos.');
}
function sessionCookie(token) { const secure = process.env.COOKIE_SECURE === 'true'; return `stores_session=${token}; HttpOnly; SameSite=${secure ? 'None' : 'Lax'}; Path=/; Max-Age=28800${secure ? '; Secure' : ''}`; }
function nav(active) {
  const items = [
    ['dashboard', '⌂', 'Resumen', '/storeadmin/'],
    ['stores', '▣', 'Tiendas', '/storeadmin/stores'],
    ['catalog', '◇', 'Categorías', '/storeadmin/catalog'],
    ['products', '⬡', 'Productos', '/storeadmin/products'],
    ['settings', '⚙', 'Configuración', '/storeadmin/settings'],
  ];
  return `<aside class="side">${items.map(([key, icon, label, href]) => `<a class="${active === key ? 'active' : ''}" href="${href}"><span class="nav-icon" aria-hidden="true">${icon}</span><span>${label}</span></a>`).join('')}<a href="/storeadmin/logout"><span class="nav-icon" aria-hidden="true">⇥</span><span>Cerrar sesión</span></a></aside>`;
}
