const server = http.createServer(async (req, res) => {
  try {
    const pathname = new URL(req.url, `http://${req.headers.host || 'localhost'}`).pathname;
    const host = String(req.headers.host || '').split(':')[0];
    if ((host === 'importacionesebc.store' || host === 'www.importacionesebc.store') && (pathname === '/storeadmin' || pathname === '/storeadmin/')) return redirect(res, '/admin');
    if (pathname.startsWith('/storeadmin/uploads/')) {
      const filename = path.basename(pathname);
      try {
        const file = await fs.readFile(path.join(uploadDir, filename));
        return send(res, 200, file, 'image/webp; charset=binary', { 'cache-control': 'public, max-age=31536000, immutable' });
      } catch {
        return send(res, 404, 'No encontrado', 'text/plain; charset=utf-8');
      }
    }
    if (pathname.startsWith('/storeadmin/api/')) return await handleApi(req, res, pathname);
    if (pathname.startsWith('/storeadmin')) return await handleAdmin(req, res, pathname);
    return send(res, 404, 'No encontrado', 'text/plain; charset=utf-8');
  }
  catch (error) { send(res, 500, { error: 'Error interno del servidor.' }); console.error(error); }
});

await fs.mkdir(uploadDir, { recursive: true });
await db.init(seed);
server.listen(port, () => console.log(`Stores Admin escuchando en http://localhost:${port}/storeadmin/`));
